package kvlines

import (
	"errors"
	"strconv"
	"strings"
	"unicode/utf8"
)

type entry struct{ key, value string }

var errSyntax = errors.New("syntax error")

func isBlank(c byte) bool { return c == ' ' || c == '\t' }
func isLower(c byte) bool { return c >= 'a' && c <= 'z' }
func isDigit(c byte) bool { return c >= '0' && c <= '9' }
func isWord(c byte) bool  { return isLower(c) || isDigit(c) || c == '_' || c == '-' }
func isHex(c byte) bool {
	return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func lstrip(s string) string {
	a := 0
	for a < len(s) && isBlank(s[a]) {
		a++
	}
	return s[a:]
}

func strip(s string) string {
	a, b := 0, len(s)
	for a < b && isBlank(s[a]) {
		a++
	}
	for b > a && isBlank(s[b-1]) {
		b--
	}
	return s[a:b]
}

// scanKey returns the length of the key at the start of s (0 when there is none).
func scanKey(s string) int {
	if len(s) == 0 || !isLower(s[0]) {
		return 0
	}
	i := 1
	for i < len(s) && isWord(s[i]) {
		i++
	}
	for i < len(s) && s[i] == '.' {
		j := i + 1
		for j < len(s) && isWord(s[j]) {
			j++
		}
		if j == i+1 {
			break
		}
		i = j
	}
	return i
}

func validSection(s string) bool {
	if len(s) == 0 || !isLower(s[0]) {
		return false
	}
	for i := 1; i < len(s); i++ {
		if !isWord(s[i]) {
			return false
		}
	}
	return true
}

func parseValue(rest string) (string, error) {
	body := lstrip(rest)
	if strings.HasPrefix(body, "\"") {
		var out []byte
		i := 1
		for {
			if i >= len(body) {
				return "", errSyntax
			}
			c := body[i]
			if c == '"' {
				i++
				break
			}
			if c != '\\' {
				out = append(out, c)
				i++
				continue
			}
			i++
			if i >= len(body) {
				return "", errSyntax
			}
			switch e := body[i]; e {
			case 'n':
				out = append(out, '\n')
				i++
			case 't':
				out = append(out, '\t')
				i++
			case 'r':
				out = append(out, '\r')
				i++
			case '"', '\\':
				out = append(out, e)
				i++
			case 'u':
				if i+1 >= len(body) || body[i+1] != '{' {
					return "", errSyntax
				}
				j := strings.IndexByte(body[i+2:], '}')
				if j < 0 {
					return "", errSyntax
				}
				digits := body[i+2 : i+2+j]
				if len(digits) < 1 || len(digits) > 6 {
					return "", errSyntax
				}
				for k := 0; k < len(digits); k++ {
					if !isHex(digits[k]) {
						return "", errSyntax
					}
				}
				cp, _ := strconv.ParseUint(digits, 16, 32)
				if cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF) {
					return "", errSyntax
				}
				out = utf8.AppendRune(out, rune(cp))
				i = i + 2 + j + 1
			default:
				return "", errSyntax
			}
		}
		tail := strip(body[i:])
		if tail != "" && tail[0] != '#' {
			return "", errSyntax
		}
		return string(out), nil
	}
	cut := len(rest)
	for i := 1; i < len(rest); i++ {
		if rest[i] == '#' && isBlank(rest[i-1]) {
			cut = i
			break
		}
	}
	return strip(rest[:cut]), nil
}

func parse(text string) ([]entry, error) {
	text = strings.TrimPrefix(text, "\uFEFF")
	parts := strings.Split(text, "\n")
	if parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	section := ""
	inSection := false
	var entries []entry
	for _, raw := range parts {
		raw = strings.TrimSuffix(raw, "\r")
		for i := 0; i < len(raw); i++ {
			if (raw[i] < 32 && raw[i] != '\t') || raw[i] == 127 {
				return nil, errSyntax
			}
		}
		line := strip(raw)
		if line == "" || line[0] == '#' {
			continue
		}
		if line[0] == '[' {
			end := strings.IndexByte(line, ']')
			if end < 0 || !validSection(line[1:end]) {
				return nil, errSyntax
			}
			rest := strip(line[end+1:])
			if rest != "" && rest[0] != '#' {
				return nil, errSyntax
			}
			section = line[1:end]
			inSection = true
			continue
		}
		n := scanKey(line)
		if n == 0 {
			return nil, errSyntax
		}
		rest := lstrip(line[n:])
		if !strings.HasPrefix(rest, "=") {
			return nil, errSyntax
		}
		key := line[:n]
		if inSection {
			key = section + "." + key
		}
		v, err := parseValue(rest[1:])
		if err != nil {
			return nil, err
		}
		entries = append(entries, entry{key, v})
	}
	return entries, nil
}

func Count(text string) (int64, error) {
	es, err := parse(text)
	return int64(len(es)), err
}

func Keys(text string) ([]string, error) {
	es, err := parse(text)
	if err != nil {
		return nil, err
	}
	seen := map[string]bool{}
	out := []string{}
	for _, e := range es {
		if !seen[e.key] {
			seen[e.key] = true
			out = append(out, e.key)
		}
	}
	return out, nil
}

func Has(text, key string) (bool, error) {
	es, err := parse(text)
	if err != nil {
		return false, err
	}
	for _, e := range es {
		if e.key == key {
			return true, nil
		}
	}
	return false, nil
}

func GetAll(text, key string) ([]string, error) {
	es, err := parse(text)
	if err != nil {
		return nil, err
	}
	out := []string{}
	for _, e := range es {
		if e.key == key {
			out = append(out, e.value)
		}
	}
	return out, nil
}

func Get(text, key string) (string, error) {
	all, err := GetAll(text, key)
	if err != nil {
		return "", err
	}
	if len(all) == 0 {
		return "", errors.New("no such key")
	}
	return all[len(all)-1], nil
}

func GetInt(text, key string) (int64, error) {
	v, err := Get(text, key)
	if err != nil {
		return 0, err
	}
	digits := strings.TrimPrefix(v, "-")
	if len(digits) < 1 || len(digits) > 16 || (len(digits) > 1 && digits[0] == '0') {
		return 0, errors.New("not an integer")
	}
	for i := 0; i < len(digits); i++ {
		if !isDigit(digits[i]) {
			return 0, errors.New("not an integer")
		}
	}
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil {
		return 0, err
	}
	if n > 1<<53 || n < -(1<<53) {
		return 0, errors.New("integer out of range")
	}
	return n, nil
}

func Dump(text string) (string, error) {
	es, err := parse(text)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	for _, e := range es {
		b.WriteString(e.key)
		b.WriteString(" = \"")
		for i := 0; i < len(e.value); i++ {
			c := e.value[i]
			switch {
			case c == '\\':
				b.WriteString("\\\\")
			case c == '"':
				b.WriteString("\\\"")
			case c == '\n':
				b.WriteString("\\n")
			case c == '\t':
				b.WriteString("\\t")
			case c == '\r':
				b.WriteString("\\r")
			case c < 32 || c == 127:
				b.WriteString("\\u{" + strconv.FormatInt(int64(c), 16) + "}")
			default:
				b.WriteByte(c)
			}
		}
		b.WriteString("\"\n")
	}
	return b.String(), nil
}

