declare const require: any;
const test: any = require('node:test');
const assert: any = require('node:assert');
const fs: any = require('node:fs');
import * as lib from '../src/kv_lines';
const mod: any = lib;

function camel(s: string): string {
  return s.replace(/_([a-z0-9])/g, (_m: string, c: string) => c.toUpperCase());
}

function norm(v: any): any {
  if (v === undefined) return null;
  if (typeof v === 'number' && Object.is(v, -0)) return 0;
  if (Array.isArray(v)) return v.map(norm);
  return v;
}

test('vectors', () => {
  const file = fs.existsSync('vectors/full.json') ? 'vectors/full.json' : 'vectors/examples.json';
  const cases = JSON.parse(fs.readFileSync(file, 'utf8')).cases;
  const bad: string[] = [];
  for (const c of cases as any[]) {
    const label = `${c.fn}(${c.args.map((a: any) => JSON.stringify(a)).join(', ')})`;
    const f = mod[camel(c.fn)];
    if (typeof f !== 'function') {
      bad.push(`missing function ${camel(c.fn)}`);
      continue;
    }
    let got: any;
    let failed = false;
    try {
      got = norm(f(...c.args));
    } catch (_e) {
      failed = true;
    }
    if (c.error) {
      if (!failed) bad.push(`${label}: expected an error, got ${JSON.stringify(got)}`);
    } else if (failed) {
      bad.push(`${label}: unexpected error, want ${JSON.stringify(c.want)}`);
    } else {
      try {
        assert.deepStrictEqual(got, c.want);
      } catch (_e) {
        bad.push(`${label}: want ${JSON.stringify(c.want)}, got ${JSON.stringify(got)}`);
      }
    }
  }
  assert.strictEqual(bad.length, 0, `${bad.length} of ${cases.length} vectors failed:\n  ` + bad.slice(0, 8).join('\n  '));
});

start.vectors_test.go:
package kvlines

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	"strings"
	"testing"
)

type vxCase struct {
	Fn    string `json:"fn"`
	Args  []any  `json:"args"`
	Want  any    `json:"want"`
	Error bool   `json:"error"`
}

func vxNorm(v any) any {
	switch x := v.(type) {
	case json.Number:
		n, err := x.Int64()
		if err != nil {
			panic(err)
		}
		return n
	case []any:
		out := make([]any, len(x))
		for i := range x {
			out[i] = vxNorm(x[i])
		}
		return out
	}
	return v
}

func vxList[T any](v any, f func(any) T) []T {
	xs := v.([]any)
	out := make([]T, len(xs))
	for i, x := range xs {
		out[i] = f(x)
	}
	return out
}

func vxStr(v any) string  { return v.(string) }
func vxBool(v any) bool   { return v.(bool) }
func vxInt(v any) int64   { return v.(int64) }
func vxI32(v any) int32   { return int32(v.(int64)) }
func vxU32(v any) uint32  { return uint32(v.(int64)) }
func vxU8(v any) uint8    { return uint8(v.(int64)) }

func vxJ(v any) any {
	if v == nil {
		return nil
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return rv.Int()
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return int64(rv.Uint())
	case reflect.String:
		return rv.String()
	case reflect.Bool:
		return rv.Bool()
	case reflect.Slice:
		out := make([]any, rv.Len())
		for i := range out {
			out[i] = vxJ(rv.Index(i).Interface())
		}
		return out
	}
	panic(fmt.Sprintf("unsupported result type %T", v))
}

func vxShow(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		return fmt.Sprint(v)
	}
	return string(b)
}

func vxCall(fn string, a []any) (got any, failed bool, known bool) {
	switch fn {
	case "count":
		r, err := Count(vxStr(a[0]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "keys":
		r, err := Keys(vxStr(a[0]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "has":
		r, err := Has(vxStr(a[0]), vxStr(a[1]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "get":
		r, err := Get(vxStr(a[0]), vxStr(a[1]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "get_all":
		r, err := GetAll(vxStr(a[0]), vxStr(a[1]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "get_int":
		r, err := GetInt(vxStr(a[0]), vxStr(a[1]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "dump":
		r, err := Dump(vxStr(a[0]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	}
	return nil, false, false
}

func vxRun(c vxCase) (got any, failed bool, known bool, pan any) {
	defer func() {
		if r := recover(); r != nil {
			pan = r
		}
	}()
	got, failed, known = vxCall(c.Fn, c.Args)
	return
}

func TestVectors(t *testing.T) {
	path := "vectors/examples.json"
	if _, err := os.Stat("vectors/full.json"); err == nil {
		path = "vectors/full.json"
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var doc struct {
		Cases []vxCase `json:"cases"`
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	if err := dec.Decode(&doc); err != nil {
		t.Fatal(err)
	}
	bad := []string{}
	for _, c := range doc.Cases {
		c.Args = vxNorm(c.Args).([]any)
		c.Want = vxNorm(c.Want)
		parts := make([]string, len(c.Args))
		for i, a := range c.Args {
			parts[i] = vxShow(a)
		}
		label := c.Fn + "(" + strings.Join(parts, ", ") + ")"
		got, failed, known, pan := vxRun(c)
		switch {
		case !known:
			bad = append(bad, "missing function "+c.Fn)
		case pan != nil:
			bad = append(bad, fmt.Sprintf("%s: panic: %v", label, pan))
		case c.Error:
			if !failed {
				bad = append(bad, fmt.Sprintf("%s: expected an error, got %s", label, vxShow(got)))
			}
		case failed:
			bad = append(bad, fmt.Sprintf("%s: unexpected error, want %s", label, vxShow(c.Want)))
		case !reflect.DeepEqual(got, c.Want):
			bad = append(bad, fmt.Sprintf("%s: want %s, got %s", label, vxShow(c.Want), vxShow(got)))
		}
	}
	if len(bad) > 0 {
		shown := bad
		if len(shown) > 8 {
			shown = shown[:8]
		}
		t.Fatalf("%d of %d vectors failed:\n  %s", len(bad), len(doc.Cases), strings.Join(shown, "\n  "))
	}
}

solution.kv_lines.py:
import re

_KEY = re.compile(r"[a-z][a-z0-9_-]*(?:\.[a-z0-9_-]+)*")
_SECTION = re.compile(r"[a-z][a-z0-9_-]*")
_HEX = re.compile(r"[0-9a-fA-F]{1,6}")
_INT = re.compile(r"-?(?:0|[1-9][0-9]{0,15})")
_BLANKS = " \t"


def _lines(text):
    if text.startswith("\ufeff"):
        text = text[1:]
    parts = text.split("\n")
    if parts[-1] == "":
        parts.pop()
    return [p[:-1] if p.endswith("\r") else p for p in parts]


def _value(rest):
    body = rest.lstrip(_BLANKS)
    if body.startswith('"'):
        out = []
        i = 1
        while True:
            if i >= len(body):
                raise ValueError("unterminated string")
            c = body[i]
            if c == '"':
                i += 1
                break
            if c != "\\":
                out.append(c)
                i += 1
                continue
            i += 1
            if i >= len(body):
                raise ValueError("dangling backslash")
            e = body[i]
            if e in "ntr":
                out.append({"n": "\n", "t": "\t", "r": "\r"}[e])
                i += 1
            elif e in '"\\':
                out.append(e)
                i += 1
            elif e == "u":
                if body[i + 1:i + 2] != "{":
                    raise ValueError("bad unicode escape")
                j = body.find("}", i + 2)
                if j < 0 or not _HEX.fullmatch(body[i + 2:j]):
                    raise ValueError("bad unicode escape")
                cp = int(body[i + 2:j], 16)
                if cp > 0x10FFFF or 0xD800 <= cp <= 0xDFFF:
                    raise ValueError("bad code point")
                out.append(chr(cp))
                i = j + 1
            else:
                raise ValueError("unknown escape")
        tail = body[i:].strip(_BLANKS)
        if tail and tail[0] != "#":
            raise ValueError("junk after string")
        return "".join(out)
    cut = len(rest)
    for i in range(1, len(rest)):
        if rest[i] == "#" and rest[i - 1] in _BLANKS:
            cut = i
            break
    return rest[:cut].strip(_BLANKS)


def _parse(text):
    section = None
    entries = []
    for raw in _lines(text):
        if any((ord(c) < 32 and c != "\t") or ord(c) == 127 for c in raw):
            raise ValueError("control character")
        line = raw.strip(_BLANKS)
        if not line or line[0] == "#":
            continue
        if line[0] == "[":
            end = line.find("]")
            if end < 0 or not _SECTION.fullmatch(line[1:end]):
                raise ValueError("bad section header")
            rest = line[end + 1:].strip(_BLANKS)
            if rest and rest[0] != "#":
                raise ValueError("junk after section header")
            section = line[1:end]
            continue
        m = _KEY.match(line)
        if not m:
            raise ValueError("bad key")
        rest = line[m.end():].lstrip(_BLANKS)
        if not rest.startswith("="):
            raise ValueError("missing =")
        key = m.group(0) if section is None else section + "." + m.group(0)
        entries.append((key, _value(rest[1:])))
    return entries


def count(text):
    return len(_parse(text))


def keys(text):
    seen = []
    for k, _ in _parse(text):
        if k not in seen:
            seen.append(k)
    return seen


def has(text, key):
    return any(k == key for k, _ in _parse(text))


def get(text, key):
    found = [v for k, v in _parse(text) if k == key]
    if not found:
        raise KeyError(key)
    return found[-1]


def get_all(text, key):
    return [v for k, v in _parse(text) if k == key]


def get_int(text, key):
    v = get(text, key)
    if not _INT.fullmatch(v):
        raise ValueError("not an integer")
    n = int(v)
